<?php $sm=array();foreach($schedules as $r)$sm[(int)$r['day_of_week']]=$r; ?>
<div class="heading"><div><h1><?= $barber && !empty($barber['id'])?'Editar peluquero':'Nuevo peluquero' ?></h1><p>Datos, servicios, días y horarios de trabajo.</p></div></div><?php if($errors): ?><div class="errors"><ul><?php foreach($errors as $e): ?><li><?= h($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><section class="card"><?= form_open($barber && !empty($barber['id'])?'peluqueros/actualizar/'.$barber['id']:'peluqueros/guardar') ?><div class="formgrid"><div class="field"><label class="required">Nombre y apellido</label><input class="input" name="full_name" value="<?= h($barber['full_name']??'') ?>" required></div><div class="field"><label>Teléfono</label><input class="input" name="phone" value="<?= h($barber['phone']??'') ?>"></div><div class="field"><label class="required">Porcentaje</label><input class="input" type="number" min="0" max="100" step="0.01" name="commission_percent" value="<?= h($barber['commission_percent']??'50') ?>" required></div><div class="check"><label><input type="checkbox" name="active" value="1" <?= !isset($barber['active'])||$barber['active']?'checked':'' ?>> Peluquero activo</label></div></div><div class="divider"></div><div class="cardhead"><div><h3>Servicios que realiza</h3><p>Se usan para validar los turnos</p></div></div><div class="service-picker"><?php foreach($services as $s): ?><label class="service-option"><input type="checkbox" name="service_ids[]" value="<?= $s['id'] ?>" <?= in_array((int)$s['id'],$selected_services)?'checked':'' ?>><span><strong><?= h($s['name']) ?></strong><small><?= money($s['price']) ?> · <?= (int)$s['duration_minutes'] ?> min</small></span></label><?php endforeach; ?></div><div class="divider"></div><div class="cardhead"><div><h3>Días y horarios</h3><p>El sistema impedirá turnos fuera de estos rangos</p></div></div><?php for($d=1;$d<=7;$d++): $r=$sm[$d]??NULL; ?><div class="schedule-grid"><div class="day"><?= h(day_name($d)) ?></div><label class="checkday"><input type="checkbox" name="day_<?= $d ?>" value="1" <?= $r?'checked':'' ?>> Trabaja</label><input class="input" type="time" name="start_<?= $d ?>" value="<?= h($r?substr($r['start_time'],0,5):'09:00') ?>"><input class="input" type="time" name="end_<?= $d ?>" value="<?= h($r?substr($r['end_time'],0,5):'18:00') ?>"></div><?php endfor; ?><div class="form-actions"><a class="btn" href="<?= site_url('peluqueros') ?>">Cancelar</a><button class="btn primary" type="submit">Guardar peluquero</button></div><?= form_close() ?></section>